 margin:8px 0 10px;padding:12px 14px;border:3px solid #6e4e20;border-radius:18px;
 background:
  radial-gradient(circle at 72% -30%,#27642d88,transparent 45%),
  linear-gradient(180deg,#213c20,#0b170e 70%);
 box-shadow:inset 0 0 0 1px #ba8b38,0 10px 28px #000a;display:flex;align-items:center;justify-content:space-between;gap:12px
}
.v4107-brand{display:flex;align-items:center;gap:10px}.v4107-brand-mark{font-size:34px;filter:drop-shadow(0 3px 4px #000)}
.v4107-brand h1{margin:0;color:#f4d56e;font-size:clamp(20px,3vw,36px);letter-spacing:.025em;text-shadow:0 3px 0 #2e1c08}
.v4107-brand h1 span{color:#7ff14c}.v4107-brand p{margin:3px 0 0;color:#a9bca6;font-size:8px;font-weight:800}
.v4107-version{padding:7px 10px;border:2px solid #57923b;border-radius:10px;background:#112415;color:#96f26a;font-size:10px;font-weight:1000;white-space:nowrap}
.v4107-layout{display:grid;grid-template-columns:205px minmax(0,1fr) 235px;gap:8px;align-items:start}
.v4107-sidebar,.v4107-panel,.v4107-right-card{
 border:2px solid #4b613a;border-radius:15px;background:linear-gradient(180deg,#101c12,#071009);
 box-shadow:inset 0 0 0 1px #1e311e,0 7px 19px #0008
}
.v4107-sidebar{position:sticky;top:7px;padding:7px;overflow:hidden}
.v4107-side-title{padding:10px 9px;margin:-2px -2px 6px;border-bottom:1px solid #4f6339;background:linear-gradient(#263520,#161f15);font-size:10px;font-weight:1000;color:#f3ecd3}
.v4107-nav{width:100%;display:flex;align-items:center;gap:8px;margin:4px 0;padding:9px 8px;border:1px solid transparent;border-radius:9px;background:#0a130d;color:#cbd7c8;text-align:left;font:900 8px/1.25 inherit;
